css:
:root{--ink:#17202a;--mute:#566274;--blue:#2563eb;--blue-d:#1d4ed8;--tint:#eef3fe;--line:#dde3ec;--sans:var(--page-sans),'Pretendard','Noto Sans KR','Apple SD Gothic Neo',system-ui,sans-serif;--num:var(--page-display),'Outfit',var(--page-sans),sans-serif}
*{box-sizing:border-box}
.cl{font-family:var(--sans);color:var(--ink);background:#fff;font-size:17px;line-height:1.75;word-break:keep-all;overflow-wrap:break-word}
.cl *{margin:0}
.cl-wrap{max-width:1080px;margin:0 auto;padding:0 28px}
.cl a:focus-visible,.cl summary:focus-visible,.cl-row:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
.cl-hero{padding:72px 0 64px;border-bottom:1px solid var(--line)}
.cl-name{font-size:18px;font-weight:700;color:var(--blue);margin-bottom:14px}
.cl-h1{font-size:44px;line-height:1.25;font-weight:800;letter-spacing:-.02em;max-width:18em}
.cl-lead{margin-top:20px;max-width:38em;color:var(--mute);font-size:18px}
.cl-proof{margin-top:48px;padding:28px;background:var(--tint);border-radius:6px}
.cl-proof-t{font-weight:700;font-size:17px;margin-bottom:20px}
.cl-bars{display:grid;gap:12px}
.cl-barrow{display:grid;grid-template-columns:72px 1fr;align-items:center;gap:14px}
.cl-barlabel{font-size:14px;color:var(--mute);font-weight:600}
.cl-track{display:block;height:34px;background:#fff;border:1px solid var(--line);border-radius:3px;position:relative;overflow:hidden}
.cl-fill{display:block;height:100%;background:#9fb4d6;width:100%;transform-origin:left;animation:clgrow 1.1s cubic-bezier(.2,.7,.2,1) both}
.cl-fill.is-new{background:var(--blue);width:16.7%;animation-delay:.5s}
.cl-val{position:absolute;left:12px;top:0;line-height:34px;font-size:14px;font-weight:700;color:#fff;white-space:nowrap}
.cl-val.dark{color:var(--ink)}
@keyframes clgrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.cl-proofnote{margin-top:18px;font-size:15px;color:var(--mute);display:flex;flex-wrap:wrap;gap:6px 28px}
.cl-proofnote b{color:var(--ink);font-family:var(--num);font-weight:700}
.cl-sec{padding:80px 0;border-bottom:1px solid var(--line)}
.cl-h2{font-size:28px;line-height:1.4;font-weight:800;letter-spacing:-.015em;max-width:24em}
.cl-p{margin-top:18px;max-width:40em}
.cl-defs{margin-top:40px;display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:2px solid var(--ink)}
.cl-def{padding:20px 24px 4px 0}
.cl-def+.cl-def{padding-left:24px;border-left:1px solid var(--line)}
.cl-def dt{font-weight:800;font-size:18px}
.cl-def dd{color:var(--mute);margin-top:4px;font-size:16px}
.cl-meta{margin-top:10px;color:var(--mute);font-size:15px;font-weight:600}
.cl-story{margin-top:44px;display:grid;gap:0;border-left:3px solid var(--line);margin-left:6px}
.cl-step{padding:0 0 32px 28px;position:relative}
.cl-step::before{content:'';position:absolute;left:-10px;top:10px;width:17px;height:17px;border-radius:50%;background:#fff;border:3px solid var(--line)}
.cl-step.is-result::before{border-color:var(--blue);background:var(--blue)}
.cl-step h3{font-size:19px;font-weight:800}
.cl-step p{max-width:38em;margin-top:6px}
.cl-step.is-result h3{color:var(--blue)}
.cl-metrics{margin-top:24px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.cl-m{padding:22px;background:var(--tint);border-radius:6px}
.cl-m-t{font-size:15px;font-weight:700;color:var(--mute)}
.cl-m-n{font-family:var(--num);font-weight:800;font-size:40px;line-height:1.2;margin-top:6px;letter-spacing:-.02em}
.cl-m-n small{font-size:20px;font-weight:700;color:var(--mute)}
.cl-m-n em{font-style:normal;color:var(--blue)}
.cl-dots{display:grid;grid-template-columns:repeat(15,1fr);gap:4px;margin-top:14px}
.cl-dot{display:block;aspect-ratio:1;border-radius:50%;background:#c3d2ee}
.cl-dot.on{background:var(--blue)}
.cl-dot.old{background:var(--ink)}
.cl-mini{display:block;height:14px;border-radius:2px;margin-top:8px}
.cl-mini.a{background:#c3d2ee;width:100%}
.cl-mini.b{background:var(--blue);width:70%}
.cl-miniL{display:flex;justify-content:space-between;font-size:13px;color:var(--mute);margin-top:12px}
.cl-tags{margin-top:28px;display:flex;flex-wrap:wrap;gap:8px}
.cl-tag{display:inline-block;padding:4px 12px;border:1px solid var(--line);border-radius:999px;font-size:14px;font-weight:600;color:var(--ink);line-height:1.6}
.cl-split{margin-top:36px;display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.cl-two{display:grid;gap:16px}
.cl-two .cl-barrow{grid-template-columns:56px 1fr}
.cl-flow{margin-top:8px;display:grid;gap:0}
.cl-flowi{display:grid;grid-template-columns:auto 1fr;gap:14px;padding:16px 0;border-top:1px solid var(--line)}
.cl-flowi:last-child{border-bottom:1px solid var(--line)}
.cl-no{font-family:var(--num);font-weight:800;color:var(--blue);font-size:20px;line-height:1.5}
.cl-flowi b{display:block}
.cl-flowi span.t{color:var(--mute);font-size:16px;display:block}
.cl-table{margin-top:36px;border-top:2px solid var(--ink)}
.cl-row{display:grid;grid-template-columns:140px 1fr;gap:24px;padding:16px 0;border-bottom:1px solid var(--line)}
.cl-row dt{font-weight:800}
.cl-row dd{color:var(--ink)}
.cl-ev{padding:72px 0 96px}
.cl-evlist{margin-top:32px;list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0 48px}
.cl-evlist li{padding:14px 0;border-bottom:1px solid var(--line);font-size:15px;line-height:1.65;color:var(--mute)}
.cl-evlist b{display:block;color:var(--ink);font-size:16px}
.cl-evlist b i{font-style:normal;font-weight:600;font-size:13px;color:var(--blue);margin-left:8px}
@media (max-width:820px){.cl-h1{font-size:34px}.cl-defs,.cl-metrics,.cl-split,.cl-evlist{grid-template-columns:1fr}.cl-def+.cl-def{padding-left:0;border-left:0;border-top:1px solid var(--line);margin-top:16px;padding-top:20px}.cl-split{gap:32px}.cl-row{grid-template-columns:1fr;gap:2px}.cl-sec{padding:56px 0}.cl-hero{padding:48px 0}.cl-wrap{padding:0 20px}.cl-evlist{gap:0}}
@media (prefers-reduced-motion:reduce){.cl-fill{animation:none}}
